"""Offline Liberty receipt issuer. No private key is shipped or generated by CI.

Use a private folder outside any source repository; store the seed securely.
Monocypher EdDSA (BLAKE2b), not RFC8032 Ed25519. Verification in the MPC plugin.
"""
import argparse,ctypes as C,hashlib,os,platform,re,secrets,subprocess,tempfile,uuid
from pathlib import Path
VENDOR=Path(__file__).resolve().parents[1]/"plugins/Infinity/src/vendor"
def digest(p):
    h=hashlib.blake2b(digest_size=32)
    with p.open("rb") as f:
        for chunk in iter(lambda:f.read(65536),b""):h.update(chunk)
    return h.hexdigest()
def with_crypto():
    t=tempfile.TemporaryDirectory();so=Path(t.name)/"crypto.so"
    subprocess.run(["cc","-O2","-fPIC",("-dynamiclib" if platform.system()=="Darwin" else "-shared"),str(VENDOR/"monocypher.c"),"-o",str(so)],check=True)
    lib=C.CDLL(str(so))
    ptr=C.POINTER(C.c_uint8)
    lib.crypto_eddsa_key_pair.argtypes=[ptr,ptr,ptr];lib.crypto_eddsa_key_pair.restype=None
    lib.crypto_eddsa_sign.argtypes=[ptr,ptr,ptr,C.c_size_t];lib.crypto_eddsa_sign.restype=None
    return t,lib
def keypair(lib,seed):
    if len(seed)!=32:raise ValueError("Seed must be 32 bytes")
    sk=(C.c_uint8*64)();pk=(C.c_uint8*32)();s=(C.c_uint8*32).from_buffer_copy(seed)
    lib.crypto_eddsa_key_pair(sk,pk,s);return sk,bytes(pk)
def write_secret(path,seed):
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
    with os.fdopen(fd,"wb") as f:f.write(seed)
def keygen(seed_path,public_path):
    seed_path,public_path=Path(seed_path),Path(public_path)
    if seed_path.exists() or public_path.exists():raise FileExistsError("Refusing key overwrite")
    if seed_path.resolve().is_relative_to(VENDOR.parents[3]):raise ValueError("Keep the private seed outside the source repository")
    seed=secrets.token_bytes(32);t,lib=with_crypto()
    try:
        sk,pub=keypair(lib,seed);write_secret(seed_path,seed)
        with public_path.open("x") as f:f.write(pub.hex()+"\n")
        C.memset(sk,0,64)
    finally:t.cleanup()
def issue(seed_path,pack,buyer,out):
    pack,out=Path(pack),Path(out)
    if not re.fullmatch(r"[A-Za-z0-9_-]{1,64}",buyer):raise ValueError("Use a non-personal order/entitlement ID")
    lines=(pack/"Library.map").read_text(encoding="utf8").splitlines()
    if not lines or lines[0]!="LINFEXP1":raise ValueError("Unsupported map")
    ids=[x[2:] for x in lines if x.startswith("I ")]
    if len(ids)!=1 or str(uuid.UUID(ids[0]))!=ids[0]:raise ValueError("Invalid collection ID")
    identifier=ids[0];m=digest(pack/"Library.map");p=digest(pack/"Library.pcm")
    msg=f"LINFLIC2\n{identifier}\n{buyer}\n{m}\n{p}\n".encode("ascii")
    t,lib=with_crypto()
    try:
        sk,pub=keypair(lib,Path(seed_path).read_bytes());sig=(C.c_uint8*64)()
        lib.crypto_eddsa_sign(sig,sk,(C.c_uint8*len(msg)).from_buffer_copy(msg),len(msg))
        C.memset(sk,0,64)
        with out.open("x",encoding="ascii") as f:f.write(f"LINFLIC2 {identifier} {buyer} {m} {p} {bytes(sig).hex()}\n")
    finally:t.cleanup()
def policy(public_path,out):
    key=bytes.fromhex(Path(public_path).read_text().strip())
    if len(key)!=32 or not any(key):raise ValueError("Invalid production public key")
    with Path(out).open("x",encoding="ascii") as f:
        f.write("#pragma once\nconstexpr bool allowUnsignedDemo=false;\nconstexpr std::array<uint8_t,32> productionPublicKey={"+",".join(str(x) for x in key)+"};\n")
if __name__=="__main__":
    p=argparse.ArgumentParser();sp=p.add_subparsers(dest="cmd",required=True)
    k=sp.add_parser("keygen");k.add_argument("seed");k.add_argument("public")
    s=sp.add_parser("issue");s.add_argument("seed");s.add_argument("pack");s.add_argument("buyer");s.add_argument("out")
    c=sp.add_parser("policy");c.add_argument("public");c.add_argument("out")
    a=p.parse_args()
    if a.cmd=="keygen":keygen(a.seed,a.public)
    elif a.cmd=="issue":issue(a.seed,a.pack,a.buyer,a.out)
    else:policy(a.public,a.out)
